import json
from pathlib import Path
base=Path(__file__).parent
source=json.loads((base/'source.json').read_text(encoding='utf-8'))[0]['rows'][2:]
rows=[]
for r in source:
 vals=list(r.values()); rows.append(vals)
def revise(id,title,cu,pre,steps,expected):
 r=next(r for r in rows if r[1]==id)
 r[2:6]=[title,cu+'. Precondición: '+pre,'\n'.join(f'{i+1}. {s}' for i,s in enumerate(steps)),expected]
revise('AUTH-LL-01','Login con credenciales válidas','CU05','Cuenta activa y contraseña conocida en copia local.', ['Abrir /auth/Auth/Login.','Ingresar el correo y contraseña de esa cuenta.','Pulsar Ingresar y abrir Mi cuenta.'],'Se inicia sesión con la identidad y el rol correctos. Se abre el panel autorizado sin errores.')
revise('AUTH-LL-02','Login con contraseña incorrecta','CU05','Cuenta activa. Navegador sin sesión.', ['Abrir el login.','Usar el correo existente y una contraseña incorrecta.','Enviar e intentar abrir un panel protegido.'],'Se informa del fallo sin revelar datos de la cuenta. No se crea sesión ni se permite consultar el panel protegido.')
revise('AUTH-LL-03','Navegación del propietario','CU05, CU06, CU09, CU27','Propietario activo con permisos habilitados.', ['Iniciar sesión como propietario.','Abrir Mi cuenta, Trámites, Mis establecimientos y Nueva solicitud.','Volver mediante el menú.'],'Cada enlace abre el destino correspondiente con datos del propietario. No aparecen operaciones administrativas ni decisiones de otros roles.')
revise('AUTH-LL-04','Ruta protegida sin sesión','CU05','Navegador sin sesión y URL conocida de un trámite.', ['Abrir directamente /Gestion/Index.','Abrir el detalle y la descarga privada de un expediente conocido.'],'Se solicita autenticación o se deniega el acceso. No se entrega contenido del expediente ni bytes del archivo privado.')
revise('AUTH-LL-05','Cerrar sesión e impedir acceso posterior','CU05','Sesión activa.', ['Abrir Mi cuenta y pulsar Cerrar sesión.','Solicitar de nuevo el panel protegido y recargar.'],'La sesión termina. La nueva petición protegida exige autenticación. Una página conservada por el historial no permite consultar ni guardar datos nuevos.')
revise('AUTH-HL-01','Ciclo de acceso con redirección local','CU05','Sin sesión y con una URL local protegida válida.', ['Abrir esa URL.','Iniciar sesión desde la redirección al login.','Comprobar el destino y cerrar sesión.'],'Tras el login se vuelve al destino local autorizado. El cierre termina la sesión. Este caso comprueba el retorno local, además del login aislado.')
revise('AUTH-HL-02','Identidad al recargar','CU05','Sesión activa con cookie vigente.', ['Abrir una vista protegida.','Recargar y abrir otra vista del mismo rol.'],'La identidad y el rol se conservan durante la sesión vigente. No se mezclan datos de otra cuenta.')
revise('AUTH-HL-03','Aislamiento entre propietarios','CU09, CU07','Dos propietarios A y B con solicitudes y archivos distintos.', ['Entrar como A.','Abrir por URL el detalle de B.','Solicitar la descarga de un documento de B.'],'Se deniega o no se encuentra el recurso ajeno sin exponer datos ni archivos. El listado de A solo contiene sus trámites.')
revise('PUB-LL-01','Cargar portal público','CU01, CU02','Copia local con laboratorios visibles y sin sesión.', ['Abrir /.','Revisar directorio, filtros, mapa y enlace Requerimientos.'],'Se presenta el portal del proyecto sin exigir sesión. Directorio y filtros funcionan; si el proveedor del mapa falla, sigue disponible la consulta de fichas.')
revise('PUB-LL-02','Buscar por nombre parcial','CU02','Laboratorio visible con nombre único y otro que no coincide en nombre, tipo ni servicios.', ['Buscar una parte única del nombre.','Comparar resultados de la lista y el mapa.'],'Solo aparecen coincidencias del buscador. La lista y los marcadores corresponden al mismo conjunto; se conserva el texto buscado.')
revise('PUB-LL-03','Filtrar por tipo','CU02','Dos tipos con laboratorios visibles.', ['Seleccionar uno de los tipos y buscar.','Cambiar al otro y buscar.'],'Cada resultado tiene el tipo elegido. El selector conserva el valor y el mapa coincide con la lista.')
revise('PUB-LL-04','Filtrar por estado de atención','CU02','Un laboratorio abierto y otro cerrado que sean visibles en el entorno de prueba.', ['Filtrar Abierto.','Repetir con Cerrado y con cualquier estado.'],'Cada consulta respeta el estado de atención. La selección no altera la habilitación ni los datos almacenados.')
revise('PUB-LL-05','Combinar criterios y limpiar filtros','CU02','Datos con y sin coincidencia para texto, tipo y estado.', ['Aplicar texto, tipo y estado compatibles.','Cambiar el texto por uno sin coincidencias.','Quitar los criterios y buscar.'],'Se cumple la intersección de filtros. Sin coincidencias se informa el estado vacío sin marcadores antiguos. Al limpiar reaparece el conjunto correspondiente.')
revise('PUB-LL-06','Detalle público de laboratorio','CU03','Ficha visible con servicios, dirección, teléfono y código conocidos.', ['Abrir Ver detalle desde el directorio.','Comparar la información con el registro de prueba.'],'Se muestra el laboratorio seleccionado y sus datos públicos disponibles. Los ausentes no se inventan. No se exponen propietario, documentos privados ni credenciales.')
revise('PUB-LL-07','Marcadores coherentes con el estado','CU02','Mapa disponible y laboratorios visibles abiertos y cerrados.', ['Localizar en el mapa ambos laboratorios.','Abrir sus ventanas de información y sus detalles.'],'Los marcadores distinguen los estados de forma consistente. Nombre y estado coinciden con las fichas; se puede conocer el estado mediante texto.')
revise('PUB-LL-08','Destino de Cómo llegar','CU04','Laboratorio con coordenadas válidas.', ['Abrir su detalle y pulsar Cómo llegar.','Comprobar la ficha de ruta y el destino del enlace a Maps.'],'La ruta conserva el laboratorio y sus coordenadas como destino. No genera origen personal sin solicitar ubicación.')
revise('PUB-HL-01','Recorrido público de búsqueda a ruta','CU02, CU03, CU04','Laboratorio conocido y visible.', ['Buscar y filtrar hasta encontrarlo.','Abrir detalle y luego Cómo llegar.','Volver al directorio mediante los enlaces.'],'Se mantiene la identidad del laboratorio en la secuencia y el regreso funciona sin autenticación ni enlaces rotos.')
revise('PUB-HL-02','Ruta con ubicación autorizada','CU04','Prueba manual con navegador compatible. Persona informada autoriza compartir su ubicación con Google Maps.', ['Abrir la ruta de un laboratorio conocido.','Pulsar Usar mi ubicación y conceder el permiso manualmente.','Comprobar el enlace o página de Maps.'],'El origen corresponde a la ubicación concedida y el destino al laboratorio. No se certifica precisión física ni tiempo de viaje. Sin permiso o ubicación disponible, usar los casos negativos independientes.')
revise('REG-LL-01','Abrir nueva solicitud','CU06','Propietario activo con permiso solicitudes.', ['Abrir Nueva solicitud.','Revisar datos generales, municipio, coordenadas, requisitos y selección de archivos.'],'Se muestra el formulario de apertura con instrucciones legibles. Permite guardar borrador y completar requisitos sin exigir adjuntar todos los PDF a la vez.')
revise('REG-LL-02','Obligatorios de nueva apertura','CU06','Propietario y copia local sin solicitudes creadas por esta prueba.', ['Guardar el formulario vacío.','Repetir dejando vacío un campo obligatorio cada vez, incluidos espacios solos.','Corregir todos los obligatorios.'],'Cada intento inválido identifica el campo y no crea solicitud. El intento válido permite guardar un único borrador. PDF no es obligatorio para guardar borrador.')
revise('REG-LL-03','Coordenadas actualizan el mapa','CU06','Mapa disponible.', ['Ingresar latitud -17.39 y longitud -66.16.','Cambiar ambas a otro punto válido y salir del campo.'],'Marcador y previsualización usan los valores ingresados sin intercambiar latitud y longitud ni cambiar sus signos.')
revise('REG-LL-04','Arrastrar el marcador','CU06','Mapa y marcador disponibles.', ['Arrastrar el marcador a un punto identificable.','Comparar la nueva posición con los campos y guardar el borrador.','Reabrir el detalle.'],'Los campos se actualizan y la ubicación guardada coincide con el marcador elegido.')
revise('REG-LL-05','PDF válido en carga inicial','CU07','PDF sintético estructuralmente válido menor de 10 MB y formulario válido.', ['Agregar el PDF a la lista de carga inicial.','Guardar borrador.','Abrir el documento desde el expediente.'],'El archivo queda asociado al borrador y se descarga con autorización. La carga inicial no acredita por sí sola un requisito hasta asociarlo.')
revise('REG-LL-06','Archivo distinto de PDF en registro','CU07','TXT sintético y formulario válido.', ['Seleccionar el TXT, usando Todos los archivos si el selector lo requiere.','Intentar guardar con ese archivo.'],'Se rechaza el archivo con un mensaje claro. No se conserva como documento válido ni se envía la solicitud a revisión.')
revise('REG-LL-07','Guardar borrador sin archivos','CU06','Propietario autorizado y datos generales válidos.', ['Completar todos los datos obligatorios, incluido municipio.','Guardar sin adjuntar archivos.','Abrir Trámites y su detalle.'],'Se crea una solicitud propia en borrador. Los requisitos pendientes se muestran y el registro no se confunde con un envío a revisión.')
revise('REG-HL-01','Apertura completa hasta revisión','CU06, CU07, CU08','Catálogo activo con requisitos obligatorios conocidos y PDF sintéticos para cada uno.', ['Crear un borrador válido.','Cargar documentos y asociarlos a los requisitos.','Completar todos los obligatorios.','Enviar solicitud y abrirla como coordinador.'],'Pasa de borrador a en_revision una sola vez. El coordinador ve los archivos actuales y la referencia de requisitos del primer envío. Todavía no existe habilitación.')
revise('REG-HL-02','Corregir un formulario inválido','CU06','Formulario de nueva apertura sin guardar.', ['Intentar guardar con un dato obligatorio inválido.','Corregirlo; volver a seleccionar el archivo si el navegador vació el selector.','Guardar y consultar el listado.'],'El intento inválido no crea registros ni archivos huérfanos. El envío corregido crea un borrador. Los valores válidos no sensibles se mantienen cuando corresponde.')
revise('REG-HL-03','Formulario adaptable a móvil','CU06','Navegador de prueba con anchos de 1366 y 390 px.', ['Abrir nueva solicitud en ambos tamaños.','Recorrer campos, mapa y lista de archivos.','Abrir menú y llegar a Guardar usando teclado o toque.'],'Campos, errores y botones son legibles y operables sin solapamiento ni desplazamiento horizontal de la página. La emulación no acredita un dispositivo físico.')
revise('SEG-LL-01','Listado de trámites propios','CU09','Propietario con apertura borrador y renovación enviada.', ['Abrir Trámites.','Comparar identificadores y estados con las dos solicitudes.'],'Se listan las solicitudes propias con apertura/renovación y estado correcto. Mis establecimientos lista laboratorios, no sustituye el listado de trámites.')
revise('SEG-LL-02','Detalle propio e historial','CU09, CU12','Solicitud propia con historial y versiones de documento.', ['Abrir el detalle desde Trámites.','Revisar datos, documentos actuales/anteriores e historial.'],'Los datos son legibles, las versiones se distinguen y el historial presenta actor/fecha/acción. No aparecen formularios de decisión ajenos al rol.')
revise('SEG-LL-03','Enviar borrador completo','CU08','Borrador propio con todos los obligatorios actuales satisfechos y sin documentos observados.', ['Abrir detalle.','Pulsar Enviar solicitud y recargar.'],'Estado en_revision, historial y confirmación coherentes. Ya no permite editar datos ni archivos como si siguiera en borrador.')
revise('SEG-LL-04','Reenviar desde pestaña obsoleta','CU08','El mismo borrador completo abierto en dos pestañas.', ['Enviar desde la primera pestaña.','Intentar enviar desde la segunda sin recargar.','Revisar historial y listado.'],'La segunda operación se rechaza o informa que cambió el trámite. No duplica envío, historial ni notificaciones de la decisión.')
revise('SEG-LL-05','Estados legibles y diferenciados','CU09','Solicitudes de prueba en borrador, en_revision, aprobado, inspeccion, revision_acta, observado, rechazado, revision_legal y habilitado.', ['Consultar listado y detalle de cada estado.','Comparar etiqueta, siguiente acción y botones permitidos.'],'Cada estado tiene texto comprensible además del color. Aprobado indica documentación conforme; solo habilitado indica resolución legal positiva. No se ofrecen saltos de etapa.')
revise('SEG-HL-01','Listado refleja el primer envío','CU08, CU09','Borrador completo y listado abierto en otra pestaña.', ['Consultar su detalle y enviarlo.','Regresar al listado y actualizar la segunda pestaña.'],'Ambas consultas actualizadas muestran en_revision y el mismo identificador. El propietario conserva acceso al expediente.')
revise('SEG-HL-02','Persistencia tras nueva sesión','CU08, CU09','Solicitud enviada a revisión sin decisiones concurrentes.', ['Anotar identificador y estado.','Recargar, cerrar sesión y volver a entrar con la misma cuenta.','Abrir ese trámite.'],'La solicitud mantiene estado en_revision, archivos e historial. La recarga o nueva sesión no crea solicitudes ni modifica su estado.')
revise('SEG-HL-03','Navegación autenticada del propietario','CU05, CU06, CU09, CU27','Sesión de propietario vigente.', ['Ir de Trámites a Nueva solicitud.','Volver a Mi cuenta y Mis establecimientos.','Usar enlaces de regreso al listado.'],'Cada enlace lleva a la sección indicada, conserva la identidad y resalta la sección actual. No existen destinos rotos o menús repetidos que ejecuten acciones diferentes.')

groups={
 'AUTH':('SQA-01','auth/'), 'PUB':('SQA-02','publico/'), 'REG':('SQA-03','solicitud-registro/'),
 'SEG':('SQA-04','solicitud-seguimiento/'), 'COO':('SQA-05','coordinacion/'),
 'SUP':('SQA-06','supervision/'), 'LEG':('SQA-07','revision-legal/'),
 'ADM':('SQA-08','administracion/'), 'MET':('SQA-09','metricas/'),
 'NOT':('SQA-10','notificaciones/'), 'SEC':('SQA-11','seguridad/'),
 'OPS':('SQA-12','continuidad-local/'), 'E2E':('SQA-13','transversal/')}
counts={}
def add(group,cu,title,pre,steps,expected):
 counts[group]=counts.get(group,0)+1
 qa,module=groups[group]
 rows.append([qa,f'{group}-EXT-{counts[group]:02}',title,cu+'. Precondición: '+pre,'\n'.join(f'{i+1}. {s}' for i,s in enumerate(steps)),expected,'No ejecutado',module,'QASE'])

# Casos añadidos. Cada repetición parametrizada se registra por separado al ejecutar.
add('AUTH','CU05','Login con campos vacíos o correo inválido','Sin sesión.', ['Enviar correo y contraseña vacíos.','Repetir con correo mal formado y contraseña conocida.'],'Se identifican los errores sin crear sesión. El servidor rechaza los mismos valores si se omite la validación del navegador.')
add('AUTH','CU05','Cuenta inactiva o inexistente','Una cuenta suspendida y un correo inexistente.', ['Intentar entrar con cada cuenta y contraseña de prueba.'],'No se inicia sesión. Los mensajes no exponen contraseña, hash ni detalles internos.')
add('AUTH','CU05','Límite temporal de intentos','Prueba técnica en copia local sin otros usuarios conectados.', ['Enviar más de 30 intentos de login en menos de un minuto desde la misma IP.','Esperar a la siguiente ventana y repetir un acceso válido.'],'Los excesos reciben 429 sin sesión. Tras renovarse la ventana vuelve a permitirse un intento válido; no es un bloqueo permanente de la cuenta.')
add('AUTH','CU05','Destino externo tras login','Sin sesión. Cuenta válida.', ['Abrir login con returnUrl=https://example.invalid.','Iniciar sesión.'],'La redirección externa se ignora y el usuario permanece en el proyecto, en un destino local autorizado.')
add('AUTH','CU05, CU22','Revocar una sesión por cambio administrativo','Usuario de prueba conectado y administrador en otro navegador.', ['Modificar el usuario desde administración.','Con su sesión anterior solicitar un recurso protegido.','Entrar de nuevo con la configuración vigente.'],'La sesión anterior deja de ser válida. La nueva sesión respeta rol, estado y credenciales vigentes.')
add('AUTH','CU05, CU23','Matriz de acceso de los seis roles','Una cuenta activa de cada perfil con permisos habilitados.', ['Para cada rol abrir su panel y tarea principal.','Intentar por URL una función exclusiva de cada uno de los otros cinco roles.'],'Las tareas propias funcionan y las ajenas se deniegan sin efectos. Guardar una evidencia por cada combinación rol/destino.')
add('PUB','CU02','Búsqueda por tipo y servicio','Datos visibles cuyo tipo o servicio contiene un texto único ausente del nombre.', ['Buscar el texto del tipo.','Repetir con el texto del servicio.'],'Se encuentran los laboratorios correspondientes y no solo coincidencias del nombre. Lista y mapa permanecen sincronizados.')
add('PUB','CU01, CU24','Consultar requisitos por secciones','Sección activa con requisito obligatorio, opcional y plantilla PDF.', ['Abrir Requerimientos sin sesión.','Revisar agrupación, orden y obligatoriedad.','Descargar la plantilla publicada.'],'Se ven secciones y requisitos activos en orden con obligatoriedad clara. La plantilla es pública; no se muestran archivos privados de solicitudes.')
add('PUB','CU01, CU24','Catálogo público vacío o desactivado','Copia local con catálogo vacío; segunda variante con secciones y requisitos inactivos.', ['Abrir Requerimientos en cada variante.'],'Se informa que no hay requisitos publicados sin inventar una lista. Los requisitos inactivos o de sección inactiva no aparecen.')
add('PUB','CU04','Denegar ubicación en ruta','Prueba manual con permisos restablecidos por la persona usuaria.', ['Pulsar Usar mi ubicación.','Denegar el permiso manualmente.','Usar Elegir origen en Google Maps.'],'Se muestra una explicación de ubicación denegada y una alternativa manual. No hay bloqueo continuo ni se comparte una ubicación que no se autorizó.')
add('PUB','CU04','Ubicación no disponible, lenta o no soportada','Prueba técnica con proveedor de ubicación simulado, sin datos personales.', ['Ejecutar por separado error de disponibilidad, timeout y navegador sin geolocalización.','Reintentar o usar origen manual.'],'Cada escenario informa el fallo y permite continuar. No abre rutas con coordenadas ausentes, inválidas o antiguas.')
add('PUB','CU04','Elegir el abierto más cercano','Fixture con origen sintético conocido, dos abiertos a distancias distintas y un cerrado aún más próximo.', ['Filtrar el conjunto y pulsar Cómo llegar al abierto más cercano.','Conceder el origen de prueba.'],'El destino es el abierto de menor distancia geográfica entre los resultados filtrados. No se elige el cerrado ni se promete optimización por tráfico.')
add('PUB','CU04','Más cercano sin abiertos','Filtro que devuelve solo cerrados o ningún registro.', ['Pulsar Cómo llegar al abierto más cercano.'],'Se informa que no hay laboratorios abiertos con esos filtros. No se solicita ubicación innecesaria ni se abre Maps sin destino.')
add('PUB','CU02, CU03','Mapa externo no disponible','Navegador de prueba con Leaflet o mapas externos bloqueados temporalmente.', ['Cargar directorio y ficha.','Buscar y consultar coordenadas y datos.'],'Se informa que el mapa no está disponible. Listado, ficha y navegación del proyecto siguen utilizables sin error de JavaScript que los bloquee.')
add('PUB','CU03','Ficha inexistente y coordenadas inválidas','ID inexistente y registro de prueba con ubicación ausente o fuera de rango.', ['Abrir el ID inexistente.','Consultar el registro sin ubicación válida.'],'No se muestra otro laboratorio por defecto. No se generan marcadores o rutas con coordenadas inválidas; la ficha disponible informa sus limitaciones.')
add('PUB','CU03, CU28','Vigencia vencida y datos incompletos','Registros de prueba vencidos y con propietario/vigencia ausentes.', ['Consultar directorio y ficha.','Comparar con el estado calculado y los avisos de datos pendientes.'],'No se presenta vigencia vencida como vigente ni se inventan propietario o fecha. Se respetan las reglas de publicación del entorno local sin clasificar registros por ser dummy.')

add('REG','CU06','Límites exactos de coordenadas','Formulario válido sin archivos.', ['Probar latitud -90 y 90, longitud -180 y 180.','Repetir con -90.000001, 90.000001, -180.000001 y 180.000001 en el campo respectivo.','Repetir con coordenada vacía o texto.'],'Se aceptan los límites inclusivos válidos. Cada valor exterior, incompleto o no numérico se rechaza sin crear registros. No se redondea un valor inválido hasta hacerlo válido.')
add('REG','CU06','Tipos y municipios activos','Catálogos con opción activa e inactiva en cada clase.', ['Guardar una apertura con opciones activas.','Intentar por petición manipulada una opción inexistente o inactiva.'],'Solo se acepta una opción activa cuando existe catálogo de esa clase. No basta cambiar el texto o el identificador del formulario.')
add('REG','CU06','Longitudes y caracteres de datos generales','Prueba técnica y formulario válido de referencia.', ['Para cada campo textual probar su máximo declarado y un carácter más.','Repetir con espacios solos en obligatorios, controles no permitidos y teléfono inválido.'],'Se aplican límites del modelo y reglas de cada campo tanto en cliente como servidor. El error identifica el campo y no deja datos parciales.')
add('REG','CU07','Agregar más de cinco PDF uno a uno','Seis PDF sintéticos válidos, cada uno menor de 10 MB y total menor de 50 MB.', ['Seleccionar uno, abrir de nuevo el selector y agregar otro hasta seis.','Revisar la lista y guardar el borrador.'],'Las selecciones se acumulan. Se conservan los seis archivos y no se aplica un límite de cinco al expediente.')
add('REG','CU07','Quitar y volver a añadir antes de guardar','Tres PDF válidos en la lista inicial sin guardar.', ['Quitar el segundo archivo.','Cancelar una apertura del selector.','Agregar otro PDF y guardar.'],'Cancelar no vacía la lista. Solo se guardan los archivos que quedaron seleccionados, sin incluir el retirado ni duplicar los demás.')
add('REG','CU07','PDF falsificado o incompleto','TXT renombrado a .pdf y PDF sin cierre, sintéticos.', ['Intentar cada archivo en carga inicial y carga individual.'],'Ambos se rechazan por contenido inválido aunque la extensión sea .pdf. No aparecen como documentos actuales ni se conservan archivos rechazados.')
add('REG','CU07','Tamaño por PDF y total inicial','Archivos sintéticos en el límite de 10 MB y un byte por encima; conjunto de hasta 50 MB y otro superior.', ['Cargar PDF válido de hasta 10 MB.','Repetir con más de 10 MB.','Probar los conjuntos iniciales dentro y fuera del máximo de 50 MB.'],'Se admiten tamaños válidos con estructura PDF correcta. Se rechaza cada exceso sin guardado parcial; el límite conjunto no sustituye el límite individual.')
add('REG','CU07','Cuerpo de petición excesivo','Prueba técnica en copia local.', ['Enviar carga inicial con longitud declarada mayor de 55 MB.','Enviar carga individual mayor de 11 MB.','Probar también un cuerpo sin longitud que exceda sus límites.'],'Los excesos se rechazan de forma controlada, 413 cuando corresponde. No se agota la lectura sin límite ni se crean solicitudes o documentos parciales.')
add('REG','CU06','Editar datos solo antes del primer envío','Apertura propia en borrador, apertura enviada y renovación.', ['Editar nombre o coordenadas del primer borrador y guardar.','Intentar la misma edición tras enviar y en la renovación.'],'Solo el borrador inicial propio sin primer envío ni laboratorio vinculado admite esa edición. Las demás variantes se rechazan en servidor.')

add('SEG','CU07','Carga individual posterior al borrador','Borrador propio y requisito pendiente.', ['Cargar un PDF desde el detalle y recargar.','Cargar después otro PDF para un requisito distinto.'],'Cada carga queda guardada sin exigir subir nuevamente los archivos anteriores. No envía automáticamente el expediente a revisión.')
add('SEG','CU07','Asociar carga inicial sin volver a subir','Borrador con PDF complementario actual y requisito pendiente.', ['Asociar ese PDF al requisito.','Recargar y descargar.'],'El requisito queda cubierto por el mismo documento/archivo sin duplicar la carga. Se registra la asociación y la versión del trámite.')
add('SEG','CU07','Reemplazar documento observado conservando versiones','Expediente propio editable con documento observado y motivo.', ['Cargar un PDF corregido para el mismo requisito.','Consultar documento actual y versiones anteriores.'],'Solo la nueva versión queda actual y pendiente de revisión. Se conserva archivo, motivo, autor y fecha de la versión anterior.')
add('SEG','CU07','Proteger documentos aprobados','Expediente editable con un documento aprobado.', ['Intentar reemplazar o retirar el documento aprobado.','Repetir por petición directa si el botón está oculto.'],'El servidor rechaza la operación. El documento aprobado conserva archivo y condición de actual hasta una observación autorizada.')
add('SEG','CU07, CU08','Retirar documento y reponer obligatorio','Borrador propio con obligatorio pendiente y complemento pendiente.', ['Retirar el complemento y comprobar historial.','Retirar el obligatorio.','Intentar enviar y luego reponer el obligatorio.'],'Las retiradas conservan historial y archivo. Sin obligatorio actual se bloquea el envío; al reponerlo vuelve a poder completarse. No se borran pruebas históricas.')
add('SEG','CU08','Impedir envío con faltantes u observados','Borrador o devolución propia con un obligatorio ausente y otro documento observado.', ['Intentar enviar.','Completar el obligatorio y volver a intentar sin corregir el observado.'],'Ambos intentos se bloquean con explicación específica. Un complemento no asociado no sustituye el obligatorio y un observado no se considera corregido.')
add('SEG','CU08, CU24','Congelar requisitos en el primer envío','Catálogo conocido, solicitud enviada y otro borrador sin enviar.', ['Modificar nombre, sección u obligatoriedad de un requisito como administrador.','Abrir ambas solicitudes.','Subsanar y reenviar la primera.'],'La enviada y sus reenvíos conservan la copia original. El borrador toma el catálogo publicado vigente hasta su primer envío.')
add('SEG','CU08','Catálogo sin requisitos obligatorios','Copia local con requisitos opcionales o catálogo vacío y borrador válido.', ['No adjuntar archivos artificiales y enviar.'],'La ausencia de obligatorios no exige inventar un PDF. Se permite el flujo previsto y se preserva la referencia de requisitos correspondiente.')
add('SEG','CU27','Consultar establecimiento y expedientes','Propietario con laboratorio vinculado a apertura y renovación.', ['Abrir Mis establecimientos y su ficha.','Acceder a cada expediente y documento autorizado.'],'Se vincula el laboratorio correcto y se mantienen separados apertura y renovación. No se muestran establecimientos de otro propietario.')
add('SEG','CU27','Editar solo servicios y detectar edición simultánea','Laboratorio propio abierto en dos pestañas.', ['Cambiar servicios en la primera y guardar.','Guardar otro texto desde la segunda sin recargar.','Intentar alterar propietario, vigencia o estado en la petición.'],'Se conserva el primer cambio y se rechaza el obsoleto con 409. Solo servicios puede editarse por esta acción; los datos oficiales no cambian.')
add('SEG','CU32','Crear renovación del laboratorio propio','Establecimiento propio elegible sin renovación activa.', ['Solicitar renovación y abrir el borrador.','Comparar vínculo y datos del establecimiento.'],'Se crea una renovación propia ligada al mismo laboratorio. No crea un laboratorio nuevo ni modifica su vigencia antes de la resolución legal.')
add('SEG','CU32','Bloquear renovaciones activas duplicadas','Renovación activa del mismo laboratorio; incluir rechazado de campo reprogramable.', ['Intentar iniciar otra renovación en cada estado activo.','Repetir con propietario distinto.'],'No se permite duplicar mientras exista un trámite activo, incluido rechazo de campo reprogramable. Tampoco puede renovarse el laboratorio ajeno.')
add('SEG','CU32','Ventana anticipada configurable','Copia local con ventana de renovación configurada y vigencias de prueba.', ['Solicitar renovación fuera de la ventana.','Repetir en su primer día permitido y tras vencer.'],'La ventana configurada se respeta sin rechazar su límite permitido. Sin configuración no se inventa una restricción anticipada nueva.')

add('COO','CU10','Bandeja de coordinación por tareas','Coordinador y solicitudes en revisión documental, asignación y revisión de acta.', ['Abrir cada filtro rápido.','Aplicar estado y municipio y entrar al detalle.','Volver a la bandeja.'],'Cada filtro muestra la etapa correspondiente sin borradores ajenos a la coordinación. Las acciones y etiquetas indican la siguiente tarea sin duplicar decisiones.')
add('COO','CU10','Aprobar documento actual','Documento pendiente de expediente en revisión.', ['Abrir el documento y cotejar su versión.','Aprobarlo sin escribir observación de corrección.','Recargar.'],'Queda aprobado con revisor y fecha. No exige inventar una observación negativa para aprobar. La aprobación de un archivo no aprueba todo el expediente.')
add('COO','CU10','Observar documento con motivo','Documento actual pendiente.', ['Intentar observar con motivo vacío o espacios.','Escribir un motivo concreto y confirmar.'],'El primer intento se bloquea. El válido guarda motivo, revisor y fecha en ese documento, sin observar documentos no seleccionados.')
add('COO','CU10','No cerrar revisión con archivos pendientes','Expediente con todos los obligatorios y un complemento pendiente de revisión.', ['Aprobar solo los obligatorios.','Intentar aprobar documentación.','Revisar el complemento y volver a aprobar.'],'La decisión global se bloquea mientras haya documentos actuales pendientes u observados. Con todos aprobados pasa a aprobado documental, sin habilitar el laboratorio.')
add('COO','CU10','Devolución documental sin repetir motivos','Expediente en revisión con uno o más documentos observados y motivos individuales.', ['Devolver para subsanación sin duplicar el texto en un comentario general.','Abrir como propietario y corregir los archivos indicados.','Reenviar y revisar de nuevo.'],'Se reutilizan los motivos documentales. El propietario ve qué corregir y el reenvío vuelve a revisión documental, conservando decisiones y versiones anteriores.')
add('COO','CU10','Rechazo documental definitivo','Expediente en revisión documental.', ['Intentar rechazar sin fundamento.','Rechazar con fundamento concreto.','Intentar asignar supervisor o reenviar como propietario.'],'El rechazo exige motivo, queda definitivo y no se reactiva mediante asignación o envío. El historial lo distingue de la devolución subsanable.')
add('COO','CU10','Revisión de versión obsoleta o documento ajeno','Dos pestañas de revisión y documento de otra solicitud.', ['Revisar un archivo en la primera pestaña.','Guardar una revisión desde la segunda sin recargar.','Manipular el ID para usar un documento de otro expediente.'],'No se sobrescribe una revisión reciente ni se atribuye un archivo ajeno. Las operaciones inválidas no modifican el trámite.')
add('COO','CU11','Asignar supervisor sin horario','Documentación conforme y supervisor activo.', ['Asignar supervisor dejando la programación pendiente.','Entrar como supervisor y propietario.'],'La asignación aparece como pendiente de programar. No se presenta una fecha técnica como cita confirmada. Se registra el cambio y el aviso interno.')
add('COO','CU11, CU13','Asignar supervisor con intervalo','Documentación conforme, supervisor activo y horario libre.', ['Asignar con inicio y fin válidos.','Consultar agenda del supervisor y detalle del propietario.'],'Se conserva el intervalo civil de Bolivia, el supervisor y el expediente correctos. El horario queda reservado y se avisa al propietario.')
add('COO','CU11','Precondiciones de asignación','Expedientes en borrador, revisión documental incompleta, rechazo legal y habilitado; supervisor inactivo o ID inválido.', ['Intentar asignar en cada estado no permitido.','Intentar asignar un usuario no supervisor o inactivo.'],'El servidor rechaza cada combinación inválida sin visitas ni cambios de estado. No se salta documentación ni resolución legal.')
add('COO','CU19','Aceptar un acta conforme','Acta firmada registrada con resultado aprobado.', ['Abrir PDF y lista de verificación.','Aceptar el acta y consultar el trámite.'],'Se valida la inspección y el trámite pasa a revisión legal. Todavía no se habilita el laboratorio ni se extiende la vigencia.')
add('COO','CU19, CU31','Aceptar acta observada','Acta firmada observada con plazo válido.', ['Revisar y aceptar el acta.','Consultar como propietario la corrección y el plazo.'],'Se conserva resultado observado y origen de campo, con plazo de subsanación. No se presenta como habilitado ni se envía directamente a aprobación legal.')
add('COO','CU19, CU30','Devolver acta para nueva inspección','Acta registrada pendiente de validación.', ['Intentar devolver sin fundamento.','Devolver con fundamento y reprogramar con el mismo u otro supervisor.'],'Se requiere motivo, se conserva el PDF/resultado anterior y se crea el recorrido permitido de nueva visita. No se sobrescribe la inspección previa.')
add('COO','CU12, CU30','Reprogramar conservando historial y reserva','Visita pendiente programada y horario alternativo libre.', ['Reprogramar la visita y consultar historial.','Usar el intervalo anterior para otra visita.','Comprobar el nuevo horario.'],'La visita anterior permanece reprogramada y deja de reservar ese intervalo pendiente. La nueva reserva es única; no entra en conflicto consigo misma.')

add('SUP','CU13','Agenda propia y navegación temporal','Dos supervisores con visitas distintas y una asignación sin programar.', ['Entrar como uno y abrir Mi agenda.','Cambiar día/semana/mes, buscar y refrescar.'],'Solo muestra sus asignaciones con sus horarios y pendientes de programar. El refresco conserva fecha y búsqueda sin mezclar visitas ajenas.')
add('SUP','CU13','Programar intervalo válido','Última inspección propia pendiente sin horario.', ['Indicar inicio y fin con duración entre cero y 12 horas, mayor que cero.','Guardar y recargar.'],'Se reserva el horario y se registra el aviso. La hora no cambia según la zona horaria del navegador.')
add('SUP','CU13','Fechas e intervalos inválidos','Inspección propia programable.', ['Probar fin igual o anterior al inicio y duración mayor de 12 horas.','Probar una fecha ausente, imposible y con zona horaria no permitida por el contrato civil.'],'Se rechazan las variantes inválidas sin alterar la reserva previa. Los mensajes permiten corregir inicio y fin.')
add('SUP','CU13','Conflictos idénticos, parciales y envolventes','Mismo supervisor con visita reservada de 10:00 a 11:00 en un día de prueba.', ['Intentar en otra solicitud 10–11, 09:30–10:30, 10:30–11:30, 09–12 y 10:15–10:45.','Repetir tomando como reserva una visita que ya tiene acta.'],'Todos los solapamientos se bloquean, incluidos los de visitas con acta. Se conserva una sola reserva por intervalo del supervisor.')
add('SUP','CU13','Horarios contiguos y supervisores distintos','Visita de A de 10:00 a 11:00.', ['Programar A de 09:00 a 10:00 y de 11:00 a 12:00.','Programar B de 10:00 a 11:00.'],'Se admiten los intervalos contiguos y la coincidencia de distinto supervisor. La regla no bloquea un día completo ni recursos que no comparten supervisor.')
add('SUP','CU13','Dos reservas simultáneas del mismo horario','Prueba técnica local con dos solicitudes programables del mismo supervisor.', ['Enviar simultáneamente dos reservas para el mismo intervalo.','Consultar ambas y la agenda.'],'Solo una queda confirmada. La otra recibe conflicto; no quedan dos citas superpuestas aunque ambos formularios se abrieran antes de reservar.')
add('SUP','CU13','Visita nocturna y fin de calendario','Visita que cruza medianoche y fechas civiles cercanas al año 9999 en copia local.', ['Consultar ambos días de la visita nocturna.','Navegar agenda cerca del último día admitido.'],'La visita aparece en los días que ocupa y no cambia de fecha por UTC. Los límites del calendario no producen una pantalla 500.')
add('SUP','CU14','Ruta diaria ordenada','Varias visitas propias del día con coordenadas, otra sin ubicación válida y una de otro día.', ['Abrir Consultas y recorridos y elegir el día.','Comparar orden y enlaces a Maps.'],'Incluye solo las visitas que empiezan ese día ordenadas por horario. No genera destinos inválidos. No afirma optimización por tráfico ni muestra asignaciones de otro supervisor.')
add('SUP','CU15, CU16','Preparar contenido sin acta firmada','Visita propia iniciada con lista de verificación.', ['Completar la lista y guardar contenido para firma sin adjunto.','Recargar y descargar formulario o resumen.'],'El contenido se conserva como preparación. No se registra como acta firmada ni se envía a coordinación todavía. No se exige repetir hallazgos en dos campos.')
add('SUP','CU15, CU17','Observación obligatoria por incumplimiento','Lista de verificación de visita propia iniciada.', ['Marcar un punto como No cumple sin describir corrección.','Guardar; después escribir la corrección y guardar de nuevo.'],'El punto incumplido exige explicación. Cumple/No aplica no exigen una observación artificial. Las notas adicionales son opcionales y separadas de los hallazgos.')
add('SUP','CU17','Resultado global coherente','Lista con al menos un incumplimiento.', ['Intentar resultado aprobado mediante petición manipulada.','Guardar como observado y luego probar rechazo en un expediente independiente.'],'Un incumplimiento impide aprobar. Observado y rechazado siguen sus recorridos diferenciados. El resumen global se deriva de los resultados individuales.')
add('SUP','CU15, CU17','No aprobar lista totalmente No aplica','Lista de verificación no vacía en visita iniciada.', ['Marcar todos los puntos No aplica.','Intentar enviar el acta firmada.'],'No se acredita una inspección completa sin un punto aplicable. Se informa el problema y no se registra el acta final.')
add('SUP','CU15, CU16','Enviar acta firmada válida','Visita propia iniciada, lista completa con resultado coherente y PDF sintético válido.', ['Adjuntar el PDF y enviar al coordinador.','Recargar acta y abrir bandeja como coordinador.'],'Queda registrada una única acta firmada, vinculada a la visita correcta. La solicitud pasa a revisión de acta y el archivo permanece privado.')
add('SUP','CU16','Acta sin PDF, PDF inválido o anticipada','Visita futura y otra iniciada en copia local.', ['Intentar registrar acta antes del inicio.','En la iniciada intentar enviar sin PDF o con un archivo no válido.'],'No se registra acta final en ningún caso. Preparar contenido no equivale a presentar un documento firmado y no evita los controles de fecha ni archivo.')
add('SUP','CU15, CU16','Última asignación y supervisor autorizado','Expediente reasignado de A a B con inspección histórica de A.', ['A intenta programar o registrar la nueva acta.','B consulta su última inspección y los archivos anteriores permitidos.'],'Solo B modifica su asignación vigente. Las versiones anteriores conservan su autor y PDF; no se toma el formulario de otro supervisor como actual.')
add('SUP','CU15, CU24','Lista y plantilla congeladas por visita','Visita asignada con plantilla y lista versión 1.', ['Modificar catálogo y plantilla como administrador.','Abrir la visita existente.','Asignar una visita nueva independiente.'],'La visita anterior conserva su lista y plantilla copiadas. La nueva toma la versión vigente. No se reescriben hallazgos o documentos históricos.')
add('SUP','CU17, CU31','Días de subsanación y feriados','Acta observada y feriado configurado que coincide con el período.', ['Probar 0, 1, 90 y 91 días.','Guardar un plazo permitido que cruce fin de semana y feriado.'],'Solo se permiten 1–90 días cuando corresponde. El plazo cuenta días hábiles y excluye los feriados configurados; no aplica sanciones automáticas.')
add('SUP','CU18','Registrar citación con evidencia','Última visita propia con incumplimientos, trámite abierto y sin citación pendiente.', ['Completar motivo, emisión, vencimiento y anticipación.','Adjuntar PDF válido y registrar.','Descargar evidencia como actor autorizado.'],'Se asigna número interno y queda ligada a solicitud, inspección y supervisor. Los destinatarios reciben aviso interno y la descarga respeta su autorización.')
add('SUP','CU18','Evidencia de citación PNG y JPEG','Dos expedientes elegibles y archivos sintéticos válidos.', ['Registrar citación con PNG en uno y JPEG en otro.','Descargar ambas evidencias.'],'Se admiten los formatos contratados hasta 10 MB. La descarga devuelve el contenido y tipo de imagen correcto aunque el campo interno se llame EvidenciaPdf.')
add('SUP','CU18','Validación de campos y archivo de citación','Formulario elegible en copia local.', ['Probar motivo vacío, vencimiento anterior a emisión, fecha con hora y anticipación -1 o 31.','Probar evidencia ausente, extensión no permitida, contenido falsificado y tamaño excesivo.','Corregir y guardar.'],'Cada variante inválida se rechaza sin citación parcial. Anticipación 0–30 y fechas civiles válidas se aceptan junto al resto de datos correctos.')
add('SUP','CU18','Impedir citación duplicada o sin incumplimiento','Visita con citación pendiente, visita conforme y trámite cerrado.', ['Intentar nueva citación en cada escenario.'],'Se rechazan duplicados pendientes, visitas sin incumplimientos y trámites cerrados. No se reutiliza una visita histórica ajena para saltar el control.')
add('SUP','CU18, CU19','Atender citaciones con visita conforme','Citación pendiente y nueva inspección conforme.', ['Enviar el acta conforme y validarla como coordinador.','Consultar citaciones e historial.'],'Las citaciones previas quedan atendidas con fecha. Se conservan sus evidencias e historial y dejan de generar nuevos avisos de pendiente.')

add('LEG','CU-P1','Bandeja y consulta privada legal','Abogado y expedientes en revisión legal, anteriores decididos por él y otros no visibles.', ['Abrir bandeja, detalle, documentos revisados, plano/licencia disponible y acta.','Intentar un expediente fuera de su ámbito.'],'Accede a los expedientes legales y a sus decisiones previas permitidas. No se exponen documentos de solicitudes fuera de su alcance.')
add('LEG','CU-P2, CU20','Aprobar legalmente una apertura','Documentación completa revisada, acta conforme validada, datos válidos y PDF firmado sintético.', ['Adjuntar dictamen y aprobar.','Abrir expediente, laboratorio e informe.'],'Se habilita y vincula el laboratorio al propietario, se otorga un año según la fecha de aprobación y se genera cierre histórico. Solo esta decisión produce la habilitación.')
add('LEG','CU-P2','Bloquear aprobación legal incompleta','Variantes independientes: sin dictamen, PDF inválido, acta no conforme/no validada, documento pendiente, datos oficiales inválidos.', ['Intentar aprobar cada variante en copia local.'],'Se bloquea con explicación del requisito incumplido. No se crea habilitación, vigencia ni cierre parcial, incluso con petición directa.')
add('LEG','CU-P3, CU-P4','Observar solo documentos seleccionados','Revisión legal con varios documentos aprobados.', ['Observar indicando motivo y seleccionando un documento actual.','Abrir como propietario y corregir solo ese archivo.','Reenviar.'],'Solo el documento indicado pierde conformidad. Los demás mantienen su revisión. El expediente vuelve a revisión legal sin nueva visita si no fue solicitada expresamente.')
add('LEG','CU-P3','Selección documental legal inválida','Formulario de observación legal.', ['Intentar motivo vacío y ninguna selección cuando se exige corrección documental.','Manipular selección con IDs repetidos, históricos o de otro expediente.'],'Los datos inválidos se rechazan sin observar archivos ajenos ni aplicar una observación silenciosa a todos los documentos.')
add('LEG','CU-P4, CU30','Observación legal con nueva inspección','Expediente en revisión legal.', ['Observar con fundamento y marcar necesidad de nueva inspección.','Corregir y reenviar como propietario.','Seguir las etapas exigidas para volver a revisión legal.'],'Se conserva el origen legal y la indicación de nueva visita. No se habilita ni vuelve directamente a aprobación legal saltando la inspección requerida.')
add('LEG','CU-P4','Rechazo legal definitivo','Expediente legal sin resolución final.', ['Intentar rechazo sin motivo y después con motivo concreto.','Intentar reenviar o asignar supervisor tras el rechazo.'],'El rechazo válido es definitivo y conserva motivo/autor/fecha. No se reactiva mediante asignación, reenvío ni repetición de la decisión.')
add('LEG','CU20, CU32','Vigencia de renovación activa o vencida','Dos renovaciones completas: una con licencia vigente y otra vencida.', ['Aprobar ambas legalmente.','Comparar vigencia anterior, fecha de aprobación y vigencia otorgada.'],'En la vigente se añade un año desde su fin anterior; en la vencida desde la aprobación. Se conserva el mismo laboratorio y la vigencia propia de cada cierre.')
add('LEG','CU20, CU32','Integridad del vínculo de renovación','Copias locales con laboratorio ausente, propietario incompatible y vigencia no extensible del año 9999.', ['Intentar aprobar cada renovación dañada.'],'Se bloquea de forma controlada sin guardar PDF huérfano, nueva vigencia o laboratorio inventado. El lector tolerante de pantalla no autoriza datos inválidos.')
add('LEG','CU29','Informe de cierre inmutable','Apertura habilitada con informe guardado y renovación posterior.', ['Descargar el informe de apertura.','Resolver la renovación y modificar un nombre de usuario o requisito.','Descargar otra vez el informe original.'],'El informe original conserva el contenido y la vigencia de aquel cierre. La renovación dispone de su propio cierre; los cambios de catálogo no reescriben el PDF previo.')

add('ADM','CU22','Crear usuario de cada perfil','Administrador en copia local y seis correos sintéticos únicos.', ['Crear una cuenta de cada uno de los seis roles con datos válidos.','Iniciar sesión con cada cuenta y revisar su panel.'],'Cada cuenta se guarda una sola vez y entra con el rol asignado. La contraseña no aparece en listados ni respuestas y se almacena como hash.')
add('ADM','CU22','Validación de alta de usuario','Administrador y formulario de alta.', ['Probar nombre vacío o mayor de 120, correo inválido o mayor de 200.','Probar contraseña vacía, menor de 10 y mayor de 128 caracteres.','Manipular rol inexistente y opción de activo ausente/no booleana.'],'Se rechaza cada caso sin crear una cuenta parcial. El formulario conserva los errores sin pantalla 500 y nunca expone la contraseña enviada.')
add('ADM','CU22','Correo único sin distinguir mayúsculas','Usuario existente con correo conocido.', ['Intentar alta con el mismo correo en mayúsculas.','Intentar asignar ese correo a otro usuario desde edición.'],'No se duplican identidades. Se informa el conflicto sin modificar la cuenta original ni la cuenta editada.')
add('ADM','CU22','Editar usuario sin cambiar contraseña','Cuenta de prueba con contraseña conocida.', ['Cambiar nombre y guardar dejando contraseña vacía.','Iniciar nueva sesión con la contraseña anterior.'],'Se actualizan los datos solicitados y se conserva la contraseña anterior. La sesión anterior se revoca conforme al contrato.')
add('ADM','CU22','Cambiar credencial de una cuenta de prueba','Administrador y usuario sintético en copia local.', ['Asignar una contraseña nueva válida.','Intentar login con la anterior y luego con la nueva.'],'La anterior deja de servir y la nueva funciona si la cuenta sigue activa. Se revocan sesiones existentes sin revelar las credenciales en la interfaz.')
add('ADM','CU22','Suspensión y reactivación de usuario','Usuario de prueba con sesión activa sin visitas pendientes.', ['Suspenderlo como administrador.','Probar sesión anterior y nuevo login.','Reactivarlo y volver a entrar.'],'Mientras esté suspendido no accede. Al reactivar puede autenticarse con su configuración vigente y no pierde expedientes ni historial.')
add('ADM','CU22','Cambio de rol y protecciones del administrador','Usuario sin tareas incompatibles y administrador conectado.', ['Cambiar el rol del usuario y comprobar una sesión nueva.','Intentar quitarse a sí mismo el rol administrador o desactivarse.'],'El usuario recibe solo las atribuciones de su nuevo rol y su sesión anterior se revoca. El administrador no puede bloquear su propia administración con estas acciones.')
add('ADM','CU22','Supervisor con visitas pendientes','Supervisor activo asignado a una visita pendiente.', ['Intentar suspenderlo o cambiarle el rol.','Resolver o reasignar primero la visita y repetir.'],'La primera operación se bloquea para no dejar visitas sin responsable. Después de quitar la incompatibilidad puede efectuarse el cambio autorizado sin borrar historia.')
add('ADM','CU22','Edición concurrente de usuarios','Misma ficha de usuario abierta en dos pestañas.', ['Guardar un cambio en la primera.','Guardar otro desde la segunda con su versión anterior.'],'La segunda recibe conflicto y no pisa el primer cambio. Recargar permite revisar la versión actual antes de volver a guardar.')
add('ADM','CU23','Editar permisos dentro de cada perfil','Matriz de los seis roles y las 11 capacidades del catálogo.', ['Abrir Roles y permisos para cada perfil.','Desactivar una capacidad, guardar y probarla con sesión ya abierta del rol.','Reactivarla y repetir.'],'El cambio se aplica en servidor inmediatamente. Reactivar restituye la función propia; no concede funciones de otro perfil. Se registra autor, fecha y cambio.')
add('ADM','CU23','Permisos inválidos, incompletos y obsoletos','Prueba técnica local y matriz abierta en dos pestañas.', ['Enviar una capacidad ajena, duplicada o una lista incompleta.','Omitir habilitado o versión de una fila.','Guardar desde una pestaña antigua después de un cambio válido.'],'Se rechaza el formulario inválido o antiguo sin aplicar parte de la matriz. No se amplían atribuciones mediante claves manipuladas.')
add('ADM','CU24','Crear y editar sección de requisitos','Administrador autorizado.', ['Crear sección con nombre, descripción, orden y activa.','Editar nombre, descripción y orden.','Consultar Requerimientos.'],'La sección se publica en el orden definido cuando está activa. La edición incrementa su versión sin alterar expedientes ya enviados.')
add('ADM','CU24','Desactivar sección y reactivarla','Sección con requisitos individualmente activos e inactivos.', ['Desactivar la sección y consultar catálogo público y borradores.','Reactivarla y consultar otra vez.'],'Desactivar oculta sus requisitos publicados sin cambiar el estado individual. Reactivar solo vuelve a publicar los que también estén activos y no eliminados.')
add('ADM','CU24','Eliminar sección con y sin requisitos','Dos secciones: una vacía y otra con requisitos no eliminados.', ['Intentar eliminar la sección con requisitos.','Eliminar la vacía y revisar el catálogo.'],'La sección con requisitos no eliminados no se elimina. La vacía admite baja lógica y desaparece del catálogo sin borrar archivos ni referencias históricas.')
add('ADM','CU24','Alta y edición de requisito con plantilla','Sección activa y PDF sintético válido.', ['Crear requisito, indicar sección, orden, obligatoriedad y estado.','Adjuntar plantilla y guardar.','Editar y consultar requisitos públicos y borrador nuevo.'],'Se publica la configuración vigente y la plantilla pública correcta. Obligatorio/opcional es explícito; no se confunde plantilla con documento del propietario.')
add('ADM','CU24','Activar, desactivar y eliminar requisito','Requisito ya copiado por una solicitud enviada.', ['Desactivarlo y revisar el catálogo y expediente enviado.','Reactivarlo y luego eliminarlo lógicamente.','Revisar las copias y descargas históricas.'],'El catálogo actual refleja cada acción. La baja conserva registros/archivos y la solicitud enviada mantiene su referencia histórica y evidencias.')
add('ADM','CU24','Validaciones y versión de requisitos/secciones','Formularios de sección y requisito en copia local.', ['Probar nombre vacío o mayor de 200, descripción de sección mayor de 1000, orden -1 o 10000 y sección inválida.','Probar plantilla no PDF/excesiva.','Guardar desde una versión obsoleta y manipular opciones booleanas.'],'Se rechaza cada dato inválido sin cambios parciales. Un formulario antiguo no sobreescribe una modificación reciente ni provoca error 500.')
add('ADM','CU24, CU31','Catálogos institucionales y feriados','Copia local de administración.', ['Crear/editar/desactivar tipo, municipio, punto de inspección y feriado.','Probar duplicado de nombre en la misma clase y fecha de feriado inválida.','Intentar cambiar la clase de un registro existente.'],'Se conservan clase, unicidad y formato yyyy-MM-dd de feriados. Solo opciones activas se usan en nuevas capturas; los históricos permanecen estables.')
add('ADM','CU16, CU18','Una plantilla activa por formulario','Catálogos formulario_acta y formulario_citacion con PDF válidos.', ['Activar una plantilla de cada clase.','Intentar dejar una segunda activa de la misma clase.','Descargar la plantilla correspondiente.'],'No quedan dos plantillas activas de una misma clase. Las descargas corresponden al tipo correcto y las inspecciones ya asignadas conservan su copia.')
add('ADM','CU22, CU24','Validación de datos incompletos','Registros locales heredados sin propietario/vigencia y uno con datos completos.', ['Abrir Validación de datos.','Comparar las advertencias con los registros.','Recargar sin efectuar correcciones.'],'Se señalan las carencias reales y no las inventadas. Consultar no asigna propietarios, vigencias ni una clasificación demo/oficial y no altera registros completos.')

add('MET','CU25','Métricas con totales conocidos','Gerente. Fixture: 2 habilitados, 1 rechazo definitivo, 3 pendientes enviados y 2 borradores en el período/municipio.', ['Consultar el período y municipio.','Comparar tarjetas, gráfico y tabla.'],'Total enviado = 6, habilitados = 2, rechazo definitivo = 1, pendientes = 3 y borradores separados = 2. Un rechazo de campo reprogramable cuenta pendiente. Tasa = 2/3, con el redondeo presentado.')
add('MET','CU25, CU26','Misma cohorte en pantalla, JSON y CSV','Datos con primer envío dentro/fuera del período, dos municipios, aperturas y renovaciones.', ['Aplicar Desde, Hasta y Municipio.','Actualizar gráficos, abrir detalle y descargar CSV.','Comparar los identificadores o agregados de la cohorte.'],'Los tres resultados usan la misma cohorte por primer envío y municipio, con alternativa documentada solo para legados. Incluyen el día final completo y no filtran por última modificación.')
add('MET','CU25','Promedio de cierre y ausencia de denominador','Dos cierres válidos de 2 y 4 días, uno sin fecha y otro incoherente en fixture aislado.', ['Consultar duración media.','Repetir sin cierres válidos ni decisiones definitivas.'],'El promedio válido es 3 días. Sin cierres válidos no se inventa cero; sin decisiones la tasa queda sin dato. Fechas incoherentes no generan tiempos negativos.')
add('MET','CU25','Serie mensual, desglose y rendimiento','Cohorte de varios meses con un mes sin envíos y visitas de dos supervisores.', ['Cambiar la serie y consultar un mes.','Abrir tablas de desglose y rendimiento.'],'La serie incluye meses con cero y conserva filtros. Desgloses y rendimiento se calculan de los registros de la cohorte, sin números fijos ni doble conteo de trámites.')
add('MET','CU26','Filtros de métricas inválidos','Gerente con una consulta válida ya mostrada.', ['Probar fecha imposible, Desde mayor que Hasta y municipio demasiado largo.','Volver a una consulta válida.'],'Se informa el error sin ampliar silenciosamente el período ni generar 500. La consulta corregida funciona y no altera datos del proyecto.')
add('MET','CU26','CSV seguro y consistente','Registros sintéticos con comillas, comas, saltos de línea y texto que empieza por =, +, - o @.', ['Exportar la cohorte y abrir el CSV en una hoja de cálculo.','Comparar campos con la pantalla.'],'El CSV conserva columnas y textos, escapa separadores y neutraliza fórmulas. Los valores de texto no se ejecutan al abrirlo.')
add('MET','CU25','Actualizar gráficos ante errores y demora','Consulta válida cargada. Prueba local con red interrumpida y respuestas erróneas controladas.', ['Actualizar con corte de red, respuesta no JSON, 401/403/409/500/503 y espera superior a 15 s en ensayos separados.','Restablecer y reintentar.'],'Se informa el fallo, se conservan los últimos datos sin presentarlos como recién actualizados y el botón vuelve a estar disponible. El reintento recupera los datos.')
add('MET','CU25, CU26','Privacidad y autorización de métricas','Gerente y cada uno de los otros perfiles.', ['Consultar métricas, /Metricas/Datos y exportación con cada rol.','Inspeccionar el JSON autorizado y sus cabeceras.'],'Solo gerente autorizado obtiene los datos. El JSON contiene agregados sin correos, contraseñas o sellos de sesión y evita caché de información autorizada.')

add('NOT','CU21','Bandeja y lectura privada','Dos usuarios con avisos distintos.', ['Abrir avisos de A y marcar uno como leído.','Recargar y consultar como B.','Intentar marcar por ID un aviso de B desde A.'],'Solo el destinatario consulta o marca el aviso. La lectura persiste y no altera notificaciones ajenas.')
add('NOT','CU21','Avisos por eventos del trámite','Expediente local con actores de cada etapa.', ['Ejecutar envío, revisión documental, asignación, programación, acta, devolución y aprobación legal en recorridos válidos.','Revisar bandejas y expediente enlazado en cada etapa.'],'Los destinatarios correspondientes reciben avisos internos con trámite y acción coherentes. No se presume envío de correo/SMS ni se exige una integración no contratada.')
add('NOT','CU28','Avisos de licencia próximos y vencidos','Reloj controlado y licencias en los límites de anticipación, vigentes y vencidas.', ['Ejecutar el proceso de avisos dos veces en la misma fecha.','Avanzar al vencimiento y consultar estado/avisos.'],'Se avisa según la anticipación configurada sin duplicar la misma fase/fecha/destinatario. La licencia vencida no se presenta como vigente.')
add('NOT','CU18, CU31','Avisos de citación y subsanación','Reloj controlado, plazo hábil y citación que vence hoy con anticipación conocida.', ['Ejecutar avisos antes, durante y después del día de vencimiento.','Repetir el proceso en el mismo día y atender la citación.'],'El día de vencimiento se incluye completo. Propietario y supervisor reciben avisos sin duplicados. Atendida no sigue pendiente; vencer no aplica multa ni rechazo automático.')

add('SEC','CU05, transversal','Antifalsificación en operaciones','Prueba técnica en copia local con sesiones válidas por rol.', ['Para cada acción POST del inventario, enviar sin token y con token inválido.','Comparar base y archivos antes/después.'],'Las operaciones se rechazan sin efectos persistidos. Ocultar un botón no sustituye autorización ni protección antifalsificación.')
add('SEC','CU05, CU23','Acciones por rol y permisos suspendidos','Inventario de acciones GET/POST y las 11 capacidades configurables.', ['Ejecutar cada acción con el rol no autorizado.','Suspender su permiso y repetir con rol correcto y sesión ya abierta.','Restaurar configuración al terminar.'],'No se entregan datos ni se guarda nada en casos prohibidos. El control se aplica en servidor, incluso con una petición directa o un formulario antiguo.')
add('SEC','CU07, CU16, CU18, CU29','Matriz de descargas privadas','Archivos sintéticos de documento actual/histórico, acta, citación, dictamen e informe.', ['Descargar cada tipo con usuario autorizado, ajeno y sin sesión.','Intentar /uploads y rutas de almacenamiento.'],'Solo los actores autorizados reciben los bytes. Las plantillas publicadas se mantienen públicas; los adjuntos privados no se sirven como contenido estático.')
add('SEC','Transversal','IDs, versiones, enums y booleanos inválidos','Prueba técnica con una petición válida de cada formulario.', ['Omitir IDs/versiones obligatorios y probar valores no numéricos, negativos o inexistentes.','Alterar estado, acción, rol y booleanos con valores ajenos al contrato.','Repetir filtros GET inválidos.'],'No se crean valores por defecto ni se amplía una consulta por un filtro inválido. Se devuelve error controlado sin 500 y sin cambios parciales.')
add('SEC','Transversal','Transiciones y repetición de decisiones','Fixture independiente por combinación estado/acción/rol.', ['Intentar acciones fuera de su etapa.','Repetir decisiones ya confirmadas desde formularios antiguos.','Consultar historial y documentos.'],'Solo se aceptan transiciones del circuito autorizado. No se duplican cierres, visitas o decisiones ni se reabren rechazos definitivos.')
add('SEC','CU07, CU15, CU24','Copias JSON dañadas','Prueba técnica con copias de requisitos/lista de inspección malformadas, nulas o con IDs repetidos.', ['Abrir el detalle e intentar avanzar el trámite para cada variante.'],'Se informa inconsistencia y se bloquea el avance de forma controlada. No se reemplaza silenciosamente la copia histórica por el catálogo actual.')
add('SEC','Transversal','Contenido y nombres de archivo seguros','Textos sintéticos con etiquetas HTML/script y nombres con rutas.', ['Guardar donde el campo admita texto y volver a mostrarlo.','Cargar PDF válido con nombre que incluya componentes de ruta y descargarlo.'],'El contenido se escapa y no ejecuta scripts. El nombre visible se normaliza; la clave privada es independiente y no permite leer o escribir fuera del almacenamiento.')
add('SEC','CU09, CU12','Historial no editable desde el cliente','Expediente con varias acciones registradas.', ['Consultar actor, fecha, detalle y versiones.','Intentar alterar entradas enviando campos extras en una operación legítima.'],'El historial procede de acciones del servidor y permanece conservado. No hay una operación de cliente que permita cambiar autor, fecha o borrar entradas.')

add('OPS','Continuidad local','Restaurar respaldo completo y arrancar','Respaldo consistente con base, documentos y fuentes. Carpeta de restauración separada.', ['Verificar hashes y extraer sin sobrescribir el original.','Restaurar dependencias, compilar y arrancar en otro puerto/base.','Entrar con los seis roles y descargar muestras de cada archivo privado.'],'El proyecto recuperado arranca y conserva registros, vínculos y archivos. Integridad SQLite y claves foráneas son correctas. No se prueba solo que el ZIP pueda abrirse.')
add('OPS','Continuidad local','Corte de conexión durante carga','Copia desechable con recuento de base y archivos previo.', ['Interrumpir una carga antes de completarse.','Volver a abrir el trámite y repetir correctamente.'],'La carga incompleta no se acredita como documento ni deja registros parciales. El reintento válido funciona y no duplica el archivo registrado.')
add('OPS','Continuidad local','Reinicio inesperado durante operación','Proceso y base desechables controlados por el ensayo.', ['Interrumpir únicamente ese proceso durante una carga en curso.','Reiniciarlo y verificar integridad, sesión y expediente.'],'No hay datos confirmados a medias ni pérdida de archivos registrados. El proyecto vuelve a iniciar y una nueva operación completa funciona.')
add('OPS','Continuidad local','Almacenamiento temporalmente inaccesible','Copia desechable y copia de archivos. Fallo de almacenamiento inducido solo en esa copia.', ['Intentar guardar un PDF con almacenamiento no disponible.','Restablecerlo y reintentar.'],'Se responde 503 con posibilidad de reintentar, sin documento o solicitud parcial. Al restaurar el almacenamiento la carga vuelve a funcionar.')
add('OPS','Continuidad local','SQLite ocupada y actualización concurrente','Copia desechable. Bloqueo temporal de escritura controlado.', ['Guardar durante el bloqueo y liberarlo.','Reintentar desde datos actualizados.'],'El conflicto se informa con 409 sin error 500 ni duplicación de archivos. Después de liberar el bloqueo se puede guardar desde la versión vigente.')
add('OPS','Continuidad local','Recuperar archivo sin confirmación en base','Copia desechable con archivo de nombre generado sin referencia; otro referido solo por copia histórica.', ['Arrancar la aplicación y revisar almacenamiento y manifiesto.','Arrancarla otra vez.'],'El no referenciado se mueve a recuperación privada, nunca se borra. El referido por historial se conserva en su lugar. La segunda recuperación no duplica movimientos.')
add('OPS','Continuidad local','Recuperación conservadora ante copia histórica ilegible','Copia desechable con JSON histórico ilegible y archivo sin referencia evidente.', ['Arrancar y revisar registros y archivos.'],'Se omite la recuperación que no puede identificar todas las referencias y se informa el problema. No se mueve un archivo potencialmente histórico por suposición.')
add('OPS','Continuidad local','Exclusión de dos instancias sobre la misma base','Dos procesos controlados y la misma SQLite desechable.', ['Arrancar la primera instancia e intentar una segunda.','Detener la primera y arrancar de nuevo.'],'La segunda no opera simultáneamente sobre la misma base. Al liberar el bloqueo se permite el arranque; un archivo de bloqueo antiguo no impide iniciar por sí solo.')
add('OPS','Continuidad local','Lecturas y guardados simultáneos','Copia desechable con carga local medida y ficha de servicios abierta por varios clientes.', ['Ejecutar lecturas concurrentes y medir respuestas.','Enviar varias ediciones con la misma versión de servicios.','Comprobar integridad y valores finales.'],'No hay errores 500 ni corrupción. Solo una escritura de esa versión se confirma; las obsoletas se rechazan. Registrar tiempos observados sin inventar un SLA de producción.')
add('OPS','Instalación local','Carga inicial de usuarios y escenarios','Base nueva de Development con las opciones de carga inicial habilitadas.', ['Arrancar, entrar con cada rol y consultar sus datos de prueba.','Avanzar un trámite y reiniciar.'],'Cada perfil tiene escenarios útiles bajo las mismas reglas del sistema. Reiniciar no duplica datos, restablece contraseñas existentes ni reinicia el avance del trámite.')

add('E2E','CU06–CU20, CU-P1–CU-P4','Apertura desde borrador hasta habilitación','Copia local con catálogos y archivos sintéticos completos y actores de los seis roles.', ['Propietario crea, completa y envía.','Coordinador revisa documentos y asigna.','Supervisor programa, completa lista y envía acta firmada.','Coordinador valida y abogado aprueba con dictamen.','Propietario consulta laboratorio e informe y gerente actualiza métricas.'],'Se produce una única habilitación con propietario, vigencia, cierre y archivos correctos. Cada etapa conserva historia y avisos; las métricas reflejan el cierre sin contar el trámite dos veces.')
add('E2E','CU10, CU15, CU19, CU31, CU-P3','Recorridos de subsanación por origen','Tres solicitudes independientes: observación documental, de campo y legal.', ['Completar cada devolución y sus correcciones con el actor autorizado.','Reenviar y seguir la etapa que corresponda a su origen.'],'Documental vuelve a documentación, campo sigue el recorrido de nueva visita y legal vuelve a legal salvo nueva inspección expresa. No se mezclan ni saltan revisiones.')
add('E2E','CU32, CU20, CU29','Renovación completa e historia de apertura','Laboratorio propio con apertura cerrada y renovación elegible.', ['Crear renovación y completar documentación, visita, revisión y aprobación legal.','Consultar laboratorio e informes de ambos cierres.'],'Se conserva un solo laboratorio con vigencia extendida según la regla anual. Cada cierre mantiene su propia vigencia y PDF histórico sin reemplazar el de apertura.')
add('E2E','Transversal','Botones y enlaces por rol y estado','Inventario de pantallas, controles y estados del proyecto en copia local.', ['Para cada rol/estado registrar pantalla y control visible.','Activar cada enlace, botón, menú, selector, descarga y regreso, incluidos vacíos y formularios con errores.','Registrar resultado/evidencia por control y probar cancelaciones sin confirmar la acción.'],'Cada control tiene una acción clara y un destino correcto; no hay envíos duplicados, botones inertes ni decisiones redundantes. Cancelar no persiste cambios. Este caso requiere evidencia por control, no una marca global sin recorrido.')
add('E2E','Transversal','Accesibilidad de tareas con teclado','Cada panel y formulario de los seis roles.', ['Recorrer con Tab/Shift+Tab y activar con teclado.','Revisar foco, etiquetas, errores y controles desplegables.','Probar ampliación de texto y contraste en las vistas clave.'],'El foco es visible, el orden lógico y no hay trampas. Los controles tienen nombre y los errores se asocian al campo. Ninguna información depende solo del color.')
add('E2E','Transversal','Navegadores y tamaños de pantalla','Navegadores realmente disponibles en el equipo y emulación 390/768/1366 px.', ['Anotar navegador/versión y repetir acceso, carga, agenda, acta y gráficos en cada uno.','Comprobar menú, tablas, mapa y lista de archivos a cada ancho.'],'No hay bloqueo de tareas ni solapamientos. Registrar por separado cada navegador/tamaño y sus fallos. Emulación no certifica dispositivos físicos no utilizados.')
add('E2E','Transversal','Contenido institucional y registros pendientes','Lista de requisitos, plantillas y datos de propietarios/vigencias definitivos aprobados por la institución.', ['Comparar cada requisito, sección y formulario con la fuente suministrada.','Contrastar los tres registros heredados incompletos y sus vínculos.'],'No hay requisitos inventados ni firmas sintéticas presentadas como acreditación real. Si faltan las fuentes, registrar Bloqueado con el dato ausente, sin dar por aprobada la validación institucional.')

add('COO','CU17, CU19, CU30','Validar resultado de campo rechazado','Acta firmada con resultado rechazado e incumplimientos fundamentados.', ['Validar el resultado como coordinador.','Consultar estado y motivo del rechazo.','Asignar nueva inspección cuando corresponda subsanar campo.'],'Se conserva rechazo de origen campo como reprogramable. No se confunde con un rechazo documental o legal definitivo ni se habilita el laboratorio.')
add('SUP','CU15, CU18','Listas de actas y citaciones propias','Dos supervisores con actas registradas/validadas/rechazadas y citaciones distintas.', ['Abrir Actas emitidas y Citaciones con cada cuenta.','Abrir detalle y descargar archivos desde las filas.'],'Cada lista contiene solo registros de su supervisor y cada enlace abre la inspección correspondiente. Estado, resultado, plazo y archivo no pertenecen a otra visita.')
add('SEG','CU27','Servicios opcionales y longitud máxima','Establecimiento propio. Texto sintético sin controles.', ['Guardar servicios vacíos.','Guardar 2000 caracteres y después intentar 2001.'],'Vacío se admite al ser opcional y 2000 es el máximo permitido. El exceso no sobreescribe el valor anterior y no modifica datos oficiales.')
add('ADM','CU24, CU31','Validaciones y concurrencia de catálogos','Mismo catálogo abierto en dos pestañas.', ['Probar nombre mayor de 100 para tipo/municipio y mayor de 200 en otras clases; referencia mayor de 1000.','Guardar un cambio válido y después guardar desde la pestaña obsoleta.'],'Se respetan los límites y se rechaza el guardado obsoleto. No se cambian clase, nombre o plantilla por una petición inválida.')
add('MET','CU26','Actividad reciente y datos actuales de la cohorte','Cohorte filtrada con más de 50 movimientos y cambios de estado posteriores al período consultado.', ['Consultar los movimientos y comparar con su fecha/ID.','Revisar las métricas de la cohorte tras el cambio de estado.'],'Se muestran los 50 movimientos más recientes de esa cohorte en orden descendente. Las métricas reflejan el estado actual de sus trámites, sin fingir una reconstrucción histórica del estado al cierre del período.')
add('MET','CU26','Límite del rango de métricas','Gerente y copia local.', ['Consultar un intervalo de 3660 días y otro de 3661.','Probar Hasta igual al último día del año 9999.'],'Un rango válido de hasta 3660 días se admite. El exceso y la fecha final no extensible se rechazan de forma controlada, sin desbordamiento de fecha ni consulta ampliada.')

# Precisiones detectadas al contrastar controladores y contrato vigente.
next(r for r in rows if r[1]=='REG-EXT-03')[4]='1. Probar nombre de laboratorio hasta 200 caracteres y 201; tipo/municipio hasta 100 y 101.\n2. Probar dirección hasta 500 y 501; teléfono hasta 50 y 51; código hasta 100 y 101.\n3. Repetir con espacios solos en obligatorios, controles no permitidos y teléfono abc. Registrar cada variante por separado.'
next(r for r in rows if r[1]=='REG-EXT-03')[5]='Se admiten límites válidos con el resto de datos correctos y se rechaza cada exceso o formato inválido en servidor. Dirección, teléfono y código pueden quedar vacíos por ser opcionales. No se crean registros parciales.'
next(r for r in rows if r[1]=='LEG-EXT-04')[4]='1. Observar con motivo y seleccionar un documento actual.\n2. Como propietario corregir ese archivo y reenviar.\n3. Como coordinador revisar la corrección y aprobar la documentación.\n4. Consultar la bandeja legal.'
next(r for r in rows if r[1]=='LEG-EXT-04')[5]='Solo el documento seleccionado pierde conformidad. Después de la corrección y revisión documental, vuelve a revisión legal sin repetir una visita conforme si no se pidió nueva inspección. Los demás archivos mantienen su conformidad.'
next(r for r in rows if r[1]=='E2E-EXT-02')[5]='La corrección documental se revisa de nuevo por coordinación. Campo permite nueva visita. Legal vuelve a legal tras la revisión de los archivos corregidos, con nueva visita solo si se solicitó. No se mezclan ni saltan etapas.'
next(r for r in rows if r[1]=='SUP-EXT-08')[3]='CU14. Precondición: Varias visitas propias pendientes que empiezan ese día con coordenadas, otra sin ubicación válida y una de otro día.'
rank={k:i for i,k in enumerate(groups)}
rows=rows[:36]+sorted(rows[36:],key=lambda r:(rank[r[1].split('-')[0]],int(r[1].split('-')[-1])))
ids=[r[1] for r in rows]
assert len(ids)==len(set(ids))
assert all(len(r)==9 and all(isinstance(v,str) and v.strip() for v in r) for r in rows)
assert all(r[6]=='No ejecutado' for r in rows)
assert [r[1] for r in rows[:36]]==[list(r.values())[1] for r in source]
(base/'cases.json').write_text(json.dumps(rows,ensure_ascii=False,indent=2),encoding='utf-8')
print(json.dumps({'originales':36,'nuevos':len(rows)-36,'total':len(rows),'por_grupo_nuevo':counts},ensure_ascii=False))
